INSERT INTO locations (id, name, type, description, latitude, longitude, parent_id, state) VALUES
('d0000001-0000-0000-0000-000000000001', 'Kerala', 'state', 'Tropical Malabar Coast state known for backwaters, beaches, Ayurveda, Theyyam, and diverse cultural traditions.', 10.8505, 76.2711, NULL, 'Kerala'),
('d0000001-0000-0000-0000-000000000010', 'North Malabar', 'region', 'Northern region of Kerala encompassing Kannur, Kasaragod, and Wayanad districts. Known for Theyyam rituals, sacred groves, pristine waterfalls, and verdant forests.', 11.87, 75.37, 'd0000001-0000-0000-0000-000000000001', 'Kerala'),
('d0000001-0000-0000-0000-000000000011', 'Wayanad', 'district', 'Hill district in North Malabar with waterfalls, caves, forests, and spice plantations.', 11.68, 76.13, 'd0000001-0000-0000-0000-000000000010', 'Kerala'),
('d0000001-0000-0000-0000-000000000012', 'Kannur', 'district', 'Coastal district known for Theyyam, handloom weaving, and Fort St. Angelo.', 11.8745, 75.3704, 'd0000001-0000-0000-0000-000000000010', 'Kerala'),
('d0000001-0000-0000-0000-000000000013', 'Valiyaparamba Backwaters', 'backwater', 'Scenic backwater system in Kasaragod district — one of the most picturesque backwater regions in Kerala.', 12.08, 75.05, 'd0000001-0000-0000-0000-000000000010', 'Kerala'),
('d0000001-0000-0000-0000-000000000014', 'Meenmutty Falls', 'waterfall', 'Three-tiered waterfall in Wayanad — one of the most spectacular waterfalls in North Malabar.', 11.53, 76.00, 'd0000001-0000-0000-0000-000000000011', 'Kerala'),
('d0000001-0000-0000-0000-000000000015', 'Muzhappilangad Beach', 'beach', 'Asia''s longest drive-in beach, located in Kannur district.', 11.80, 75.45, 'd0000001-0000-0000-0000-000000000012', 'Kerala')
INSERT INTO locations (id, name, type, description, latitude, longitude, parent_id, state) VALUES
('d0000001-0000-0000-0000-000000000020', 'Jammu & Kashmir', 'state', 'Northernmost union territory with Himalayan landscapes, Dard-Shina culture, pristine valleys, and Mughal heritage.', 34.0837, 74.7973, NULL, 'Jammu & Kashmir'),
('d0000001-0000-0000-0000-000000000021', 'Gurez Valley', 'region', 'Pristine Himalayan valley at 8000 feet in Bandipora district. Home to the Dard-Shina tribal community with unique cultural traditions and the iconic Habba Khatoon peak.', 34.68, 74.83, 'd0000001-0000-0000-0000-000000000020', 'Jammu & Kashmir'),
('d0000001-0000-0000-0000-000000000022', 'Kishanganga River', 'river', 'Crystal-clear river flowing through Gurez Valley, originating from Krishansar Lake. Known as Neelum River in Pakistan.', 34.70, 74.80, 'd0000001-0000-0000-0000-000000000021', 'Jammu & Kashmir'),
('d0000001-0000-0000-0000-000000000023', 'Habba Khatoon Peak', 'mountain', 'Iconic pyramid-shaped peak in Gurez Valley, named after the legendary Kashmiri poetess.', 34.70, 74.85, 'd0000001-0000-0000-0000-000000000021', 'Jammu & Kashmir'),
('d0000001-0000-0000-0000-000000000024', 'Razdan Pass', 'mountain', 'Gateway to Gurez at 11,672 feet — breathtaking mountain pass connecting Bandipora to Gurez Valley.', 34.55, 74.75, 'd0000001-0000-0000-0000-000000000021', 'Jammu & Kashmir')
INSERT INTO locations (id, name, type, description, latitude, longitude, parent_id, state) VALUES
('d0000001-0000-0000-0000-000000000030', 'Assam', 'state', 'Northeastern state known for tea, the Brahmaputra River, one-horned rhinoceros, and Majuli river island.', 26.2006, 92.9376, NULL, 'Assam'),
('d0000001-0000-0000-0000-000000000031', 'Majuli', 'region', 'World''s largest inhabited river island in the Brahmaputra River. Cultural capital of Assamese neo-Vaishnavite culture for over 500 years. Famous for Satras, mask-making, Sattriya dance, and pottery.', 26.95, 94.15, 'd0000001-0000-0000-0000-000000000030', 'Assam'),
('d0000001-0000-0000-0000-000000000032', 'Brahmaputra River', 'river', 'Major river flowing through Assam, surrounding Majuli island. One of the largest rivers in Asia.', 26.50, 93.00, 'd0000001-0000-0000-0000-000000000030', 'Assam'),
('d0000001-0000-0000-0000-000000000033', 'Samaguri Satra', 'site', 'Famous Satra in Majuli known for 500-year-old tradition of mask-making using bamboo, cow dung, clay, and jute.', 26.97, 94.13, 'd0000001-0000-0000-0000-000000000031', 'Assam'),
('d0000001-0000-0000-0000-000000000034', 'Kaziranga National Park', 'wildlife_area', 'UNESCO World Heritage site — home to two-thirds of the world''s one-horned rhinoceros population.', 26.6340, 93.3570, 'd0000001-0000-0000-0000-000000000030', 'Assam')
INSERT INTO locations (id, name, type, description, latitude, longitude, parent_id, state) VALUES
('d0000001-0000-0000-0000-000000000040', 'Odisha', 'state', 'Eastern state with ancient Kalinga temples, tribal culture, Satkosia Gorge, Chilika Lake, and rich handicrafts.', 20.9517, 85.0984, NULL, 'Odisha'),
('d0000001-0000-0000-0000-000000000041', 'Satkosia Gorge', 'gorge', 'Spectacular 22-km gorge formed by the Mahanadi River cutting through forested Eastern Ghats hills. Part of the Satkosia Tiger Reserve established in 2006.', 20.72, 84.78, 'd0000001-0000-0000-0000-000000000040', 'Odisha'),
('d0000001-0000-0000-0000-000000000042', 'Mahanadi River', 'river', 'Major river of India flowing through Chhattisgarh and Odisha, forming the spectacular Satkosia Gorge. Length approximately 858 km.', 20.50, 85.00, 'd0000001-0000-0000-0000-000000000041', 'Odisha'),
('d0000001-0000-0000-0000-000000000043', 'Satkosia Tiger Reserve', 'wildlife_area', 'Tiger reserve established 2006, area approximately 963 sq km. Home to tigers, leopards, elephants, gharials, and over 200 bird species.', 20.75, 84.80, 'd0000001-0000-0000-0000-000000000041', 'Odisha'),
('d0000001-0000-0000-0000-000000000044', 'Konark Sun Temple', 'site', 'UNESCO World Heritage 13th-century Sun Temple — masterpiece of Kalinga architecture.', 19.8876, 86.0945, 'd0000001-0000-0000-0000-000000000040', 'Odisha'),
('d0000001-0000-0000-0000-000000000045', 'Chilika Lake', 'lake', 'Asia''s largest brackish water lagoon — important bird sanctuary and biodiversity hotspot.', 19.72, 85.32, 'd0000001-0000-0000-0000-000000000040', 'Odisha')
INSERT INTO locations (id, name, type, description, latitude, longitude, parent_id, state) VALUES
('d0000001-0000-0000-0000-000000000050', 'Amboli', 'region', 'Hill station in Sindhudurg district at 690m altitude on the Western Ghats ridge. Known as Maharashtra''s Cherrapunji with numerous monsoon waterfalls. Declared a Biodiversity Heritage Site in 2021.', 15.95, 73.87, (SELECT id FROM locations WHERE name = 'Maharashtra' AND type = 'state' LIMIT 1), 'Maharashtra'),
('d0000001-0000-0000-0000-000000000051', 'Amboli Falls', 'waterfall', 'Famous waterfall in Amboli that cascades down the Western Ghats during monsoon season.', 15.96, 73.88, 'd0000001-0000-0000-0000-000000000050', 'Maharashtra')
INSERT INTO locations (id, name, type, description, latitude, longitude, parent_id, state) VALUES
('d0000001-0000-0000-0000-000000000060', 'Chettinad', 'region', 'Region in Sivaganga district of Tamil Nadu famous for grand mansions, distinctive cuisine, and the wealthy Chettiar merchant community. On UNESCO tentative list.', 10.17, 78.78, (SELECT id FROM locations WHERE name = 'Tamil Nadu' AND type = 'state' LIMIT 1), 'Tamil Nadu'),
('d0000001-0000-0000-0000-000000000061', 'Karaikudi', 'city', 'Main town of Chettinad region — known for Athangudi tiles and Chettinad mansions.', 10.07, 78.78, 'd0000001-0000-0000-0000-000000000060', 'Tamil Nadu'),
('d0000001-0000-0000-0000-000000000062', 'Kanadukathan', 'village', 'Heritage Town in Chettinad with grand Chettiar mansions.', 10.12, 78.78, 'd0000001-0000-0000-0000-000000000060', 'Tamil Nadu')
INSERT INTO heritage_entities (id, name, category, description, location_id) VALUES
('e0000001-0000-0000-0000-000000000001', 'Theyyam', 'tradition', 'Ancient ritual art form practiced in North Malabar (Kannur, Kasaragod). Over 500 different Theyyam performances exist. Performed at Kavus (sacred groves) and Tharavadus (ancestral homes). Season: November to May.', 'd0000001-0000-0000-0000-000000000012'),
('e0000001-0000-0000-0000-000000000002', 'Valiyaparamba Backwaters', 'backwater', 'Scenic backwater system in Kasaragod district — one of the most picturesque backwater regions in Kerala, with islands and fishing villages.', 'd0000001-0000-0000-0000-000000000013'),
('e0000001-0000-0000-0000-000000000003', 'Meenmutty Falls', 'waterfall', 'Three-tiered waterfall in Wayanad — one of the most spectacular waterfalls in North Malabar, dropping from 300 meters.', 'd0000001-0000-0000-0000-000000000014'),
('e0000001-0000-0000-0000-000000000004', 'Muzhappilangad Beach', 'beach', 'Asia''s longest drive-in beach in Kannur district — a unique coastal experience in North Malabar.', 'd0000001-0000-0000-0000-000000000015'),
('e0000001-0000-0000-0000-000000000005', 'Malabar Cuisine', 'food', 'Distinctive cuisine of North Kerala including Malabar Biryani, pathiri, unnakkaya, and kallummakkaya (mussels). Known for bold spice blends and coconut-based preparations.', 'd0000001-0000-0000-0000-000000000010'),
('e0000001-0000-0000-0000-000000000006', 'Kalaripayattu', 'tradition', 'Ancient martial art tradition of Kerala — one of the oldest fighting systems in existence, with origins dating back at least 2000 years.', 'd0000001-0000-0000-0000-000000000001')
INSERT INTO heritage_entities (id, name, category, description, location_id) VALUES
('e0000001-0000-0000-0000-000000000010', 'Gurez Valley', 'cultural_site', 'Pristine Himalayan valley at 8000 feet in Bandipora district. Home to the Dard-Shina tribal community (approximately 30,000 people), descendants of ancient Aryan settlers. Features wooden villages, terraced fields, and the iconic Habba Khatoon peak.', 'd0000001-0000-0000-0000-000000000021'),
('e0000001-0000-0000-0000-000000000011', 'Dard-Shina Culture', 'community', 'Indigenous tribal community of Gurez Valley. Approximately 30,000 people who are descendants of ancient Dardic Aryan settlers. They preserve unique cultural traditions, language (Shina), and lifestyle in the remote Himalayan valley.', 'd0000001-0000-0000-0000-000000000021'),
('e0000001-0000-0000-0000-000000000012', 'Kishanganga River', 'river', 'Crystal-clear river originating from Krishansar Lake, flowing through Gurez Valley with turquoise waters. Excellent for trout fishing. Known as Neelum River in Pakistan.', 'd0000001-0000-0000-0000-000000000022'),
('e0000001-0000-0000-0000-000000000013', 'Habba Khatoon Peak', 'mountain', 'Iconic pyramid-shaped mountain dominating the Gurez Valley skyline, named after the legendary Kashmiri poetess Habba Khatoon (16th century).', 'd0000001-0000-0000-0000-000000000023'),
('e0000001-0000-0000-0000-000000000014', 'Trekking in Gurez', 'adventure', 'Multiple trekking routes through pine forests, alpine meadows, and along the Kishanganga River to remote Dard-Shina villages.', 'd0000001-0000-0000-0000-000000000021')
INSERT INTO heritage_entities (id, name, category, description, location_id) VALUES
('e0000001-0000-0000-0000-000000000020', 'Majuli', 'cultural_site', 'World''s largest inhabited river island (421 sq km) in the Brahmaputra River. Cultural capital of Assamese neo-Vaishnavite culture for over 500 years. Home to 22 Satras, mask-making, Sattriya dance, and pottery traditions.', 'd0000001-0000-0000-0000-000000000031'),
('e0000001-0000-0000-0000-000000000021', 'Satras of Majuli', 'architecture', '22 existing Vaishnavite monasteries (Satras) in Majuli, each a self-contained educational institution. Founded by Srimanta Sankerdeva and Madhavdeva in the 16th century. Preserve Sattriya dance, literature, bhaona (theatre), and mask-making.', 'd0000001-0000-0000-0000-000000000031'),
('e0000001-0000-0000-0000-000000000022', 'Mask Making of Majuli', 'craft', '500-year-old tradition of making masks from bamboo, cow dung, clay, and jute. Especially practiced at Samaguri Satra. Masks are used in bhaona (traditional theatre) performances.', 'd0000001-0000-0000-0000-000000000033'),
('e0000001-0000-0000-0000-000000000023', 'Sattriya Dance', 'tradition', 'Classical dance form from Assam, preserved in the Satras of Majuli. UNESCO Intangible Cultural Heritage. One of the eight classical dances of India.', 'd0000001-0000-0000-0000-000000000031'),
('e0000001-0000-0000-0000-000000000024', 'Mishing Community', 'community', 'Major indigenous tribal community of Majuli. Known for their distinct cultural traditions, stilt houses (Chang Ghar), and traditional fishing practices.', 'd0000001-0000-0000-0000-000000000031'),
('e0000001-0000-0000-0000-000000000025', 'Bhaona', 'tradition', 'Traditional Assamese theatre form using masks and dance, performed in the Satras of Majuli. Based on stories from the Puranas and Hindu epics.', 'd0000001-0000-0000-0000-000000000031'),
('e0000001-0000-0000-0000-000000000026', 'Raas Leela Festival', 'festival', 'Main festival of Majuli, held in mid-November. Performances based on Lord Krishna. The most important cultural event on the island.', 'd0000001-0000-0000-0000-000000000031')
INSERT INTO heritage_entities (id, name, category, description, location_id) VALUES
('e0000001-0000-0000-0000-000000000030', 'Satkosia Gorge', 'gorge', 'Spectacular 22-km gorge formed by the Mahanadi River cutting through forested Eastern Ghats hills. Part of the Satkosia Tiger Reserve. Rich biodiversity with tigers, leopards, elephants, gharials, and over 200 bird species.', 'd0000001-0000-0000-0000-000000000041'),
('e0000001-0000-0000-0000-000000000031', 'Mahanadi River', 'river', 'One of the major rivers of India (~858 km). Flows through Chhattisgarh and Odisha, forming the spectacular Satkosia Gorge. The Hirakud Dam on the Mahanadi is one of the longest dams in the world.', 'd0000001-0000-0000-0000-000000000042'),
('e0000001-0000-0000-0000-000000000032', 'Satkosia Tiger Reserve', 'wildlife', 'Tiger reserve established in 2006, area approximately 963 sq km. Home to tigers, leopards, elephants, gharials (crocodiles), mugger crocodiles, and fish eagles. Important gharial conservation site.', 'd0000001-0000-0000-0000-000000000043'),
('e0000001-0000-0000-0000-000000000033', 'Konark Sun Temple', 'monument', 'UNESCO World Heritage 13th-century Sun Temple — masterpiece of Kalinga architecture. Designed as a giant chariot with 24 wheels pulled by seven horses.', 'd0000001-0000-0000-0000-000000000044'),
('e0000001-0000-0000-0000-000000000034', 'Pattachitra', 'craft', 'Traditional scroll painting of Odisha — intricate hand-painted artwork on cloth or dried palm leaves depicting mythological narratives and tribal motifs.', 'd0000001-0000-0000-0000-000000000040'),
('e0000001-0000-0000-0000-000000000035', 'Eco-tourism at Satkosia', 'eco_tourism', 'Tikarpara and Chhotkei Nature Camps offer boating in the gorge, trekking through forested hills, and wildlife viewing. Six new ecotourism hubs planned.', 'd0000001-0000-0000-0000-000000000041'),
('e0000001-0000-0000-0000-000000000036', 'Tribal Heritage of Odisha', 'community', 'Odisha has 62 tribal groups — one of the largest tribal populations in India. Major communities include Sabar, Bhil, Santhal, and Gond with distinct art, craft, and cultural traditions.', 'd0000001-0000-0000-0000-000000000040'),
('e0000001-0000-0000-0000-000000000037', 'Chilika Lake', 'lake', 'Asia''s largest brackish water lagoon — important bird sanctuary with over 160 species of migratory birds. Home to Irrawaddy dolphins.', 'd0000001-0000-0000-0000-000000000045')
INSERT INTO heritage_entities (id, name, category, description, location_id) VALUES
('e0000001-0000-0000-0000-000000000040', 'Amboli Hills', 'natural_landmark', 'Hill station at 690m on the Western Ghats ridge. Declared a Biodiversity Heritage Site in 2021. Known as Maharashtra''s Cherrapunji for its extreme rainfall (7 meters/year).', 'd0000001-0000-0000-0000-000000000050'),
('e0000001-0000-0000-0000-000000000041', 'Amboli Waterfalls', 'waterfall', 'Numerous seasonal waterfalls cascading down the Western Ghats during monsoon (June-September). The main Amboli Falls is the most spectacular.', 'd0000001-0000-0000-0000-000000000051'),
('e0000001-0000-0000-0000-000000000042', 'Monsoon Experience at Amboli', 'adventure', 'Peak monsoon (June-August) transforms Amboli into a lush green paradise with numerous waterfalls, mist, and fog. Average annual rainfall of approximately 7 meters.', 'd0000001-0000-0000-0000-000000000050'),
('e0000001-0000-0000-0000-000000000043', 'Western Ghats Biodiversity', 'wildlife', 'Amboli Ghats is a hotspot for endemic amphibian species. Home to Malabar pit viper and other Western Ghats endemic species. Rich forest bird diversity.', 'd0000001-0000-0000-0000-000000000050')
INSERT INTO heritage_entities (id, name, category, description, location_id) VALUES
('e0000001-0000-0000-0000-000000000050', 'Chettinad Mansions', 'architecture', 'Grand palatial houses built by the wealthy Chettiar merchant community. Feature intricate woodwork, Athangudi tiles, open courtyards, Italian marble, and Burmese teak. Kanadukathan is designated as a Heritage Town.', 'd0000001-0000-0000-0000-000000000060'),
('e0000001-0000-0000-0000-000000000051', 'Chettinad Cuisine', 'food', 'One of the spiciest cuisines in India. Signature dishes include Chicken Chettinad, Kuzhi Paniyaram, and Appam with Chicken Curry. Uses fresh ground spices, coconut, and star anise.', 'd0000001-0000-0000-0000-000000000060'),
('e0000001-0000-0000-0000-000000000052', 'Athangudi Tiles', 'craft', 'Handmade terracotta floor tiles with distinctive patterns, produced in Athangudi village. Now exported worldwide. Key ingredients include local soil and natural pigments.', 'd0000001-0000-0000-0000-000000000061'),
('e0000001-0000-0000-0000-000000000053', 'Chettiar Community', 'community', 'Wealthy merchant caste (Nagarathar) who traded across Southeast Asia in the 19th-20th centuries. Built opulent mansions showcasing their prosperity and cultural values.', 'd0000001-0000-0000-0000-000000000060')
INSERT INTO chatbot_knowledge (state_code, heritage_name, heritage_type, city, historical_period, description, significance, related_event, related_person, related_craft, keywords, aliases, chatbot_question_examples, source) VALUES
('KL', 'Theyyam', 'tradition', 'Kannur/Kasaragod', 'Ancient to Present', 'Ancient ritual art form practiced in North Malabar with over 500 different performances. Performed at Kavus (sacred groves) and Tharavadus (ancestral homes). Season runs from November to May.', 'One of the most vibrant and ancient ritual art forms in India. Preserves centuries-old cultural traditions of North Malabar.', NULL, NULL, NULL, ARRAY['theyyam', 'kannur', 'kasaragod', 'ritual', 'dance', 'kavu', 'north malabar'], ARRAY['Theyyam', 'Kaliyattam'], ARRAY['Tell me about Theyyam', 'What is Theyyam in Kerala', 'Where can I see Theyyam', 'Tell me about North Malabar Theyyam'], 'Kerala Tourism'),
('KL', 'Valiyaparamba Backwaters', 'backwater', 'Kasaragod', 'Medieval to Present', 'Scenic backwater system in Kasaragod district with islands and fishing villages. One of the most picturesque backwater regions in Kerala.', 'Important eco-tourism destination showcasing the unique brackish water ecosystem of North Kerala.', NULL, NULL, NULL, ARRAY['valiyaparamba', 'backwaters', 'kasaragod', 'kerala', 'island'], ARRAY['Valiyaparamba', 'Valiyaparamba Backwaters'], ARRAY['What are backwaters in Kerala', 'Tell me about Valiyaparamba', 'Which places have backwaters'], 'Kerala Tourism'),
('KL', 'Malabar Cuisine', 'food', 'North Kerala', 'Medieval to Present', 'Distinctive cuisine of North Kerala including Malabar Biryani, pathiri, unnakkaya, and kallummakkaya (mussels). Known for bold spice blends and coconut-based preparations.', 'Represents the unique culinary heritage of North Malabar, distinct from central and south Kerala cuisine.', NULL, NULL, NULL, ARRAY['malabar', 'cuisine', 'biryani', 'pathiri', 'kerala', 'food'], ARRAY['Malabar Cuisine', 'North Kerala Food'], ARRAY['What is special about Malabar food', 'Tell me about Kerala cuisine', 'What food is famous in North Kerala'], 'Kerala Tourism'),
('KL', 'Wayanad', 'natural_landmark', 'Wayanad', 'Ancient to Present', 'Hill district in North Malabar with waterfalls (Meenmutty, Soochipara), caves (Edakkal), forests, spice plantations, and wildlife sanctuaries.', 'Important ecotourism destination in the Western Ghats biodiversity hotspot.', NULL, NULL, NULL, ARRAY['wayanad', 'waterfall', 'cave', 'forest', 'spice', 'kerala'], ARRAY['Wayanad', 'Wayanad Hills'], ARRAY['What is special about Wayanad', 'Tell me about Wayanad waterfalls', 'Show nature places in Kerala'], 'Kerala Tourism'),
('KL', 'Kalaripayattu', 'tradition', 'Kerala-wide', 'Ancient to Present', 'Ancient martial art tradition of Kerala — one of the oldest fighting systems in existence, with origins dating back at least 2000 years.', 'Recognized as one of the oldest martial arts in the world. Influenced many other Asian martial arts.', NULL, NULL, NULL, ARRAY['kalaripayattu', 'martial art', 'kerala', 'tradition'], ARRAY['Kalaripayattu', 'Kerala Martial Art'], ARRAY['Tell me about Kalaripayattu', 'What is the martial art of Kerala'], 'Kerala Tourism');
INSERT INTO chatbot_knowledge (state_code, heritage_name, heritage_type, city, historical_period, description, significance, related_event, related_person, related_craft, keywords, aliases, chatbot_question_examples, source) VALUES
('JK', 'Gurez Valley', 'cultural_site', 'Bandipora', 'Ancient to Present', 'Pristine Himalayan valley at 8000 feet in Bandipora district. Home to the Dard-Shina tribal community (approximately 30,000 people), descendants of ancient Aryan settlers. Features wooden villages, terraced fields, and the iconic Habba Khatoon peak.', 'One of the most remote and pristine valleys in Kashmir. Preserves unique Dard-Shina cultural traditions, language, and lifestyle.', NULL, NULL, NULL, ARRAY['gurez', 'valley', 'kashmir', 'dard', 'shina', 'mountain', 'habba khatoon'], ARRAY['Gurez Valley', 'Gurez'], ARRAY['Tell me about Gurez Valley', 'What is Gurez Valley', 'Tell me about Dard-Shina culture', 'Gurez Valley ke bare me batao'], 'Kashmir Tourism Official'),
('JK', 'Dard-Shina Culture', 'community', 'Gurez Valley', 'Ancient to Present', 'Indigenous tribal community of Gurez Valley. Approximately 30,000 people who are descendants of ancient Dardic Aryan settlers. They preserve unique cultural traditions, language (Shina), and lifestyle in the remote Himalayan valley.', 'The Dard-Shina community maintains one of the most unique cultural identities in the Himalayan region, with distinct language, dress, and traditions.', NULL, NULL, NULL, ARRAY['dard', 'shina', 'tribe', 'community', 'gurez', 'culture'], ARRAY['Dard-Shina', 'Dard Tribe'], ARRAY['Tell me about Dard-Shina culture', 'Who are the Dard people', 'Gurez Valley culture'], 'Kashmir Tourism Official'),
('JK', 'Kishanganga River', 'river', 'Gurez Valley', 'Ancient to Present', 'Crystal-clear river originating from Krishansar Lake, flowing through Gurez Valley with turquoise waters. Excellent for trout fishing. Known as Neelum River in Pakistan.', 'Central waterway of Gurez Valley ecosystem. Important for trout fishing and the valley''s natural beauty.', NULL, NULL, NULL, ARRAY['kishanganga', 'river', 'gurez', 'kashmir', 'trout'], ARRAY['Kishanganga', 'Neelum River'], ARRAY['What is the Kishanganga River', 'Tell me about rivers in Kashmir'], 'Kashmir Tourism Official'),
('JK', 'Habba Khatoon Peak', 'mountain', 'Gurez Valley', 'Ancient to Present', 'Iconic pyramid-shaped mountain dominating the Gurez Valley skyline, named after the legendary Kashmiri poetess Habba Khatoon (16th century).', 'The most recognizable landmark of Gurez Valley, named after the famous Kashmiri poetess who lived in the 16th century.', NULL, 'Habba Khatoon', NULL, ARRAY['habba khatoon', 'peak', 'mountain', 'gurez', 'kashmir'], ARRAY['Habba Khatoon Peak', 'Habba Khatoön'], ARRAY['What is Habba Khatoon Peak', 'Tell me about mountains in Gurez'], 'Kashmir Tourism Official');
INSERT INTO chatbot_knowledge (state_code, heritage_name, heritage_type, city, historical_period, description, significance, related_event, related_person, related_craft, keywords, aliases, chatbot_question_examples, source) VALUES
('AS', 'Majuli', 'cultural_site', 'Jorhat', '16th century to Present', 'World''s largest inhabited river island (421 sq km) in the Brahmaputra River. Cultural capital of Assamese neo-Vaishnavite culture for over 500 years. Home to 22 Satras, mask-making, Sattriya dance, and pottery traditions.', 'Often called the soul of Assam. Major cultural centre associated with neo-Vaishnavite culture, Satras, Sattriya dance, mask-making, and pottery.', NULL, 'Srimanta Sankerdeva', NULL, ARRAY['majuli', 'island', 'assam', 'satra', 'brahmaputra', 'culture'], ARRAY['Majuli', 'Majuli Island'], ARRAY['Tell me about Majuli', 'What is Majuli famous for', 'Majuli ke bare me batao', 'Tell me about Majuli island'], 'Assam Tourism'),
('AS', 'Satras of Majuli', 'architecture', 'Majuli', '16th century to Present', '22 existing Vaishnavite monasteries (Satras) in Majuli, each a self-contained educational institution. Founded by Srimanta Sankerdeva and Madhavdeva in the 16th century. Preserve Sattriya dance, literature, bhaona (theatre), and mask-making.', 'Each Satra is headed by a Satradhikar who is a learned scholar, writer, playwright, actor, and social reformer. Central to Assamese cultural identity.', NULL, 'Srimanta Sankerdeva, Madhavdeva', NULL, ARRAY['satra', 'majuli', 'monastery', 'vaishnavite', 'assam'], ARRAY['Satras', 'Vaishnavite Monasteries'], ARRAY['What are Satras in Majuli', 'Tell me about Satras in Assam'], 'Assam Tourism'),
('AS', 'Mask Making of Majuli', 'craft', 'Majuli', '16th century to Present', '500-year-old tradition of making masks from bamboo, cow dung, clay, and jute. Especially practiced at Samaguri Satra. Masks are used in bhaona (traditional theatre) performances.', 'One of the most distinctive crafts of Majuli. The Samaguri Satra is the center of this tradition.', NULL, NULL, 'Mask making', ARRAY['mask', 'majuli', 'craft', 'bamboo', 'satra', 'assam'], ARRAY['Majuli Masks', 'Mask Making'], ARRAY['Tell me about mask making in Majuli', 'What crafts are famous in Assam', 'Majuli masks bare daso'], 'Assam Tourism'),
('AS', 'Sattriya Dance', 'tradition', 'Assam', '16th century to Present', 'Classical dance form from Assam, preserved in the Satras of Majuli. UNESCO Intangible Cultural Heritage. One of the eight classical dances of India.', 'UNESCO-recognized classical dance form. Preserved and performed in the Satras of Majuli for centuries.', NULL, NULL, NULL, ARRAY['sattriya', 'dance', 'classical', 'majuli', 'assam', 'UNESCO'], ARRAY['Sattriya', 'Sattriya Dance'], ARRAY['Tell me about Sattriya dance', 'What is Sattriya', 'Classical dances of Assam'], 'UNESCO'),
('AS', 'Mishing Community', 'community', 'Majuli', 'Ancient to Present', 'Major indigenous tribal community of Majuli. Known for their distinct cultural traditions, stilt houses (Chang Ghar), and traditional fishing practices.', 'One of the three main tribal communities of Majuli along with Deori and Sonowal Kachari.', NULL, NULL, NULL, ARRAY['mishing', 'tribe', 'majuli', 'community', 'assam'], ARRAY['Mishing', 'Mishing Tribe'], ARRAY['Tell me about Mishing community', 'Who are the Mishing people'], 'Assam Tourism'),
('AS', 'Raas Leela Festival', 'festival', 'Majuli', '16th century to Present', 'Main festival of Majuli, held in mid-November. Performances based on Lord Krishna. The most important cultural event on the island.', 'The most significant festival of Majuli, drawing visitors from across Assam and beyond.', NULL, NULL, NULL, ARRAY['raas', 'leela', 'festival', 'majuli', 'krishna', 'assam'], ARRAY['Raas Leela', 'Raas Festival'], ARRAY['What is the Raas Leela festival', 'Tell me about festivals in Majuli'], 'Assam Tourism');
INSERT INTO chatbot_knowledge (state_code, heritage_name, heritage_type, city, historical_period, description, significance, related_event, related_person, related_craft, keywords, aliases, chatbot_question_examples, source) VALUES
('OD', 'Satkosia Gorge', 'natural_landmark', 'Angul/Dhenkanal', 'Ancient to Present', 'Spectacular 22-km gorge formed by the Mahanadi River cutting through forested Eastern Ghats hills. Part of the Satkosia Tiger Reserve established in 2006. Rich biodiversity with tigers, leopards, elephants, gharials, and over 200 bird species.', 'One of the most spectacular natural formations in eastern India. Important conservation area for gharials and tigers.', NULL, NULL, NULL, ARRAY['satkosia', 'gorge', 'mahanadi', 'odisha', 'tiger', 'wildlife'], ARRAY['Satkosia Gorge', 'Satkosia'], ARRAY['Tell me about Satkosia Gorge', 'What is Satkosia Gorge', 'Satkosia gorge kaha hai', 'Tell me about wildlife in Odisha'], 'Satkosia Tiger Reserve'),
('OD', 'Mahanadi River', 'river', 'Odisha/Chhattisgarh', 'Ancient to Present', 'One of the major rivers of India (~858 km). Flows through Chhattisgarh and Odisha, forming the spectacular Satkosia Gorge. The Hirakud Dam on the Mahanadi is one of the longest dams in the world.', 'Central to the ecology of Odisha. Forms the Satkosia Gorge and supports diverse wildlife.', NULL, NULL, NULL, ARRAY['mahanadi', 'river', 'odisha', 'gorge', 'hirakud'], ARRAY['Mahanadi', 'Mahanadi River'], ARRAY['Tell me about the Mahanadi River', 'What is the Mahanadi near Satkosia', 'Mahanadi river ke bare me batao'], 'Odisha Tourism'),
('OD', 'Konark Sun Temple', 'monument', 'Konark', 'Medieval (13th century)', 'UNESCO World Heritage 13th-century Sun Temple — masterpiece of Kalinga architecture. Designed as a giant chariot with 24 wheels pulled by seven horses.', 'One of the most remarkable temples in India. UNESCO World Heritage Site representing the pinnacle of Kalinga architectural tradition.', NULL, NULL, NULL, ARRAY['konark', 'sun temple', 'odisha', 'UNESCO', 'kalinga'], ARRAY['Konark', 'Konark Sun Temple'], ARRAY['Tell me about Konark Sun Temple', 'What is the Sun Temple at Konark'], 'UNESCO'),
('OD', 'Pattachitra', 'craft', 'Odisha', 'Ancient to Present', 'Traditional scroll painting of Odisha — intricate hand-painted artwork on cloth or dried palm leaves depicting mythological narratives and tribal motifs.', 'One of the oldest art forms of Odisha, recognized for its detailed craftsmanship and cultural significance.', NULL, NULL, NULL, ARRAY['pattachitra', 'painting', 'craft', 'odisha', 'art'], ARRAY['Pattachitra', 'Odisha Paintings'], ARRAY['Tell me about Pattachitra', 'What crafts are famous in Odisha'], 'Odisha Tourism'),
('OD', 'Tribal Heritage of Odisha', 'community', 'Odisha-wide', 'Ancient to Present', 'Odisha has 62 tribal groups — one of the largest tribal populations in India. Major communities include Sabar, Bhil, Santhal, and Gond with distinct art, craft, and cultural traditions.', 'Odisha''s tribal communities represent a rich cultural mosaic with unique traditions, festivals, and art forms.', NULL, NULL, NULL, ARRAY['tribal', 'odisha', 'community', 'gond', 'santhal', 'art'], ARRAY['Tribal Culture', 'Tribal Heritage'], ARRAY['Tell me about tribal culture in Odisha', 'Which tribes live in Odisha'], 'Odisha Tourism'),
('OD', 'Chilika Lake', 'lake', 'Puri/Khordha', 'Ancient to Present', 'Asia''s largest brackish water lagoon — important bird sanctuary with over 160 species of migratory birds. Home to Irrawaddy dolphins.', 'One of the most important wetlands in India for migratory birds. Major eco-tourism destination.', NULL, NULL, NULL, ARRAY['chilika', 'lake', 'odisha', 'birds', 'dolphin', 'lagoon'], ARRAY['Chilika Lake', 'Chilika'], ARRAY['Tell me about Chilika Lake', 'What is Chilika Lake'], 'Odisha Tourism');
INSERT INTO chatbot_knowledge (state_code, heritage_name, heritage_type, city, historical_period, description, significance, related_event, related_person, related_craft, keywords, aliases, chatbot_question_examples, source) VALUES
('MH', 'Amboli Hills', 'natural_landmark', 'Sindhudurg', 'Modern', 'Hill station at 690m on the Western Ghats ridge. Declared a Biodiversity Heritage Site in 2021. Known as Maharashtra''s Cherrapunji for its extreme rainfall (average 7 meters/year).', 'Officially recognized Biodiversity Heritage Site. Important for endemic amphibian species of the Western Ghats.', NULL, NULL, NULL, ARRAY['amboli', 'waterfall', 'monsoon', 'western ghats', 'maharashtra', 'biodiversity'], ARRAY['Amboli', 'Amboli Ghat', 'Amboli Hills'], ARRAY['Why is Amboli famous during monsoon', 'Tell me about Amboli', 'What is special about Amboli', 'amboli madhe pavsalyat kay pahata yetay'], 'Maharashtra Tourism'),
('MH', 'Amboli Waterfalls', 'waterfall', 'Sindhudurg', 'Modern', 'Numerous seasonal waterfalls cascading down the Western Ghats during monsoon (June-September). The main Amboli Falls is the most spectacular.', 'The waterfalls are at their most spectacular during the monsoon season, creating a lush green paradise.', NULL, NULL, NULL, ARRAY['amboli', 'waterfall', 'monsoon', 'maharashtra'], ARRAY['Amboli Falls', 'Amboli Waterfall'], ARRAY['Show waterfalls in Amboli', 'Tell me about Amboli waterfalls'], 'Maharashtra Tourism'),
('MH', 'Western Ghats Biodiversity', 'wildlife', 'Sindhudurg', 'Ancient to Present', 'Amboli Ghats is a hotspot for endemic amphibian species. Home to Malabar pit viper and other Western Ghats endemic species. Rich forest bird diversity.', 'Part of the UNESCO World Heritage Western Ghats — one of the eight hottest biodiversity hotspots in the world.', NULL, NULL, NULL, ARRAY['biodiversity', 'western ghats', 'amphibian', 'amboli', 'wildlife'], ARRAY['Western Ghats Biodiversity', 'Amboli Wildlife'], ARRAY['What wildlife is in Amboli', 'Tell me about Western Ghats biodiversity'], 'Maharashtra Tourism');
INSERT INTO chatbot_knowledge (state_code, heritage_name, heritage_type, city, historical_period, description, significance, related_event, related_person, related_craft, keywords, aliases, chatbot_question_examples, source) VALUES
('TN', 'Chettinad Mansions', 'architecture', 'Sivaganga', '19th-20th century', 'Grand palatial houses built by the wealthy Chettiar merchant community. Feature intricate woodwork, Athangudi tiles, open courtyards, Italian marble, and Burmese teak. Kanadukathan is designated as a Heritage Town.', 'On UNESCO tentative list as Chettinad, Village Clusters of the Tamil Merchants. Showcases the prosperity and cultural values of the Chettiar community.', NULL, NULL, 'Chettinad architecture', ARRAY['chettinad', 'mansion', 'architecture', 'chettiar', 'tamil nadu', 'tiles'], ARRAY['Chettinad Mansions', 'Chettinad Houses'], ARRAY['Tell me about Chettinad', 'What is special about Chettinad', 'What is Chettinad famous for', 'chettinad pathi sollunga'], 'UNESCO Tentative List'),
('TN', 'Chettinad Cuisine', 'food', 'Sivaganga', '19th century to Present', 'One of the spiciest cuisines in India. Signature dishes include Chicken Chettinad, Kuzhi Paniyaram, and Appam with Chicken Curry. Uses fresh ground spices, coconut, and star anise.', 'Renowned across India for its bold flavors and unique spice blends. Reflects the Chettiar community''s trading connections with Southeast Asia.', NULL, NULL, NULL, ARRAY['chettinad', 'cuisine', 'food', 'chicken', 'spice', 'tamil nadu'], ARRAY['Chettinad Cuisine', 'Chettinad Food'], ARRAY['Tell me about Chettinad cuisine', 'What is Chettinad food', 'What food is famous in Chettinad'], 'Tamil Nadu Tourism'),
('TN', 'Athangudi Tiles', 'craft', 'Sivaganga', '19th century to Present', 'Handmade terracotta floor tiles with distinctive patterns, produced in Athangudi village. Now exported worldwide. Key ingredients include local soil and natural pigments.', 'A unique craft tradition of Chettinad, now recognized and exported internationally.', NULL, NULL, NULL, ARRAY['athangudi', 'tiles', 'craft', 'chettinad', 'tamil nadu'], ARRAY['Athangudi Tiles', 'Chettinad Tiles'], ARRAY['What are Athangudi tiles', 'Tell me about Chettinad crafts'], 'Tamil Nadu Tourism');
